-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — NĚMECKO 2026 (10 tras, sort 3410–3500)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Eifel – Nürburgring a sopečné maary
  delete from public.routes where name = 'Eifel – Nürburgring a sopečné maary' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Eifel – Nürburgring a sopečné maary', 'Okruh srdcem sopečné Eifel spojuje dvě motorkářské svatyně: legendární Nordschleife Nürburgringu a hustou síť prázdných, perfektně zvlněných okresek mezi maary — kruhovými sopečnými jezery u Daunu. Silnice kolem okruhu jsou o víkendech plné motorek a sportovních aut, atmosféra je nezaměnitelná; kdo chce, může si za poplatek zajet turistické kolo přímo po Nordschleife. Trasa dále vede přes nejvyšší vrchol Eifel Hohe Acht ke klášteru Maria Laach na břehu sopečného jezera a zpět přes dvojité hrady v Manderscheidu. Nejlepší období je květen až říjen; pozor na měnlivé počasí a mlhy typické pro Eifel, na silnou policejní kontrolu rychlosti v okolí okruhu a na cyklisty v úzkých údolích. Povrch je vesměs výborný, zábava v zatáčkách nekončící.', 'loop', 185, 260, 'medium',
     '[{"lat": 50.3356, "lng": 6.9475, "label": "Start: Nürburg"}, {"lat": 50.38528, "lng": 7.00722, "label": "Hohe Acht"}, {"lat": 50.40222, "lng": 7.25194, "label": "Klášter Maria Laach"}, {"lat": 50.17722, "lng": 6.85056, "label": "Weinfelder Maar (Daun)"}, {"lat": 50.09556, "lng": 6.80972, "label": "Manderscheid"}, {"lat": 50.3356, "lng": 6.9475, "label": "Cíl: Nürburg"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.3356,6.9475&destination=50.3356,6.9475&travelmode=driving&waypoints=50.38528,7.00722%7C50.40222,7.25194%7C50.17722,6.85056%7C50.09556,6.80972', 'https://commons.wikimedia.org/wiki/Special:FilePath/Nordschleife%20Pflanzgarten.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nordschleife%20Pflanzgarten.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%BCrburg%20(Burg)%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kaiser-Wilhelm-Turm%20(Hohe%20Acht).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/00%200447%20Abtei%20Maria%20Laach%20-%20Deutschland.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dauner%20Maare,%20Weinfelder%20Maar%20oder%20Totenmaar.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Oberburg%20und%20Niederburg%20in%20Manderscheid.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%BCrburg%20(Burg)%2001.jpg"}'::text[], '{"Nürburgring – Nordschleife","Hrad Nürburg","Hohe Acht","Klášter Maria Laach","Weinfelder Maar (Daun)","Manderscheid – hradní dvojice","Restaurace: Pistenklause (Nürburg)"}'::text[], '{"DE"}'::text[], false, 3410, 'approved');

  -- Mosela – hrad Eltz a vinařská údolí
  delete from public.routes where name = 'Mosela – hrad Eltz a vinařská údolí' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Mosela – hrad Eltz a vinařská údolí', 'Pohodová vyjížďka nejkrásnějším vinařským údolím Německa, kde se silnice vine těsně podél meandrů Mosely mezi nejstrmějšími vinicemi Evropy. Jízda je to plynulá a nenáročná — říční silnice střídají krátké výšvihy na náhorní plošinu Hunsrücku s výhledy na říční smyčky. Vrcholem je pohádkový hrad Eltz ukrytý v lesním údolí, hradní Cochem a hrázděná městečka Beilstein a Bernkastel-Kues, kde to voní ryzlinkem. Ideální od jara do pozdního podzimu, kdy vinice hrají barvami; o víkendech počítejte s hustším turistickým provozem na břehové silnici a v obcích s radary. Skvělá trasa i pro méně zkušené jezdce a spolujezdce.', 'loop', 150, 220, 'easy',
     '[{"lat": 50.14472, "lng": 7.16833, "label": "Start: Cochem"}, {"lat": 50.20542, "lng": 7.33619, "label": "Hrad Eltz"}, {"lat": 50.10972, "lng": 7.24083, "label": "Beilstein"}, {"lat": 50.10444, "lng": 7.11278, "label": "Bremm – Calmont"}, {"lat": 49.95083, "lng": 7.115, "label": "Traben-Trarbach"}, {"lat": 49.91611, "lng": 7.07639, "label": "Bernkastel-Kues"}, {"lat": 50.14472, "lng": 7.16833, "label": "Cíl: Cochem"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.14472,7.16833&destination=50.14472,7.16833&travelmode=driving&waypoints=50.20542,7.33619%7C50.10972,7.24083%7C50.10444,7.11278%7C49.95083,7.115%7C49.91611,7.07639', 'https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Eltz%202005.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Reichsburg%20Cochem.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Eltz%202005.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Beilstein%20BW%200.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Moselschleife%20bei%20Bremm.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20Traben-Trarbach%2002.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bernkastel-Kues%20Marktplatz.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Reichsburg%20Cochem%20at%20Moselle.jpg"}'::text[], '{"Cochem – Reichsburg","Hrad Eltz","Beilstein na Mosele","Calmont – smyčka u Bremmu","Traben-Trarbach","Bernkastel-Kues","Restaurace: Alte Thorschenke (Cochem)"}'::text[], '{"DE"}'::text[], false, 3420, 'approved');

  -- Údolí Rýna – Loreley a hrady
  delete from public.routes where name = 'Údolí Rýna – Loreley a hrady' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Údolí Rýna – Loreley a hrady', 'Okruh nejslavnějším říčním kaňonem Evropy — Horním středním Porýním zapsaným na seznamu UNESCO, kde se na 65 kilometrech řeky tísní přes čtyřicet hradů. Jede se po obou březích: tam po pravém kolem Marksburgu a bájné skály Loreley, zpět po levém přes vinařský Bacharach, mohutný Rheinfels a rýnskou smyčku u Boppardu. Řeku mezi Rüdesheimem a Bingenem překonáte přívozem, což je zážitek sám o sobě. Silnice B42 a B9 jsou široké a plynulé, ideální i pro spolujezdce; techničtější pasáže si užijete na výjezdech k vyhlídkám nad údolím. Jezdit se dá od jara do podzimu, pozor na hustší provoz o letních víkendech a na železniční přejezdy podél trati.', 'loop', 135, 200, 'easy',
     '[{"lat": 50.36444, "lng": 7.60583, "label": "Start: Koblenz (Deutsches Eck)"}, {"lat": 50.2725, "lng": 7.64889, "label": "Marksburg (Braubach)"}, {"lat": 50.13944, "lng": 7.72889, "label": "Loreley"}, {"lat": 49.9875, "lng": 7.89083, "label": "Rüdesheim – Niederwald"}, {"lat": 50.05861, "lng": 7.76917, "label": "Bacharach"}, {"lat": 50.15389, "lng": 7.70528, "label": "St. Goar – Rheinfels"}, {"lat": 50.23139, "lng": 7.59083, "label": "Boppard"}, {"lat": 50.36444, "lng": 7.60583, "label": "Cíl: Koblenz"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.36444,7.60583&destination=50.36444,7.60583&travelmode=driving&waypoints=50.2725,7.64889%7C50.13944,7.72889%7C49.9875,7.89083%7C50.05861,7.76917%7C50.15389,7.70528%7C50.23139,7.59083', 'https://commons.wikimedia.org/wiki/Special:FilePath/Loreley%202025.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Deutsches%20Eck%20Koblenz.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Marksburg-Braubach.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Loreley%202025.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Germania%20-%20Niederwalddenkmal.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bacharach%20(Rhein)%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ausblick%20von%20der%20Burg%20Rheinfels%20auf%20Sankt%20Goar%20und%20Sankt%20Goarshausen%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rheinschleife-Boppard.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rheinschleife-Boppard.jpg"}'::text[], '{"Koblenz – Deutsches Eck","Marksburg","Skála Loreley","Niederwalddenkmal (Rüdesheim)","Bacharach","Hrad Rheinfels (St. Goar)","Boppard – rýnská smyčka","Restaurace: Weinhaus Heilig Grab (Boppard)"}'::text[], '{"DE"}'::text[], false, 3430, 'approved');

  -- Harz – Brocken, Wernigerode a Quedlinburg
  delete from public.routes where name = 'Harz – Brocken, Wernigerode a Quedlinburg' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Harz – Brocken, Wernigerode a Quedlinburg', 'Velký okruh nejsevernějším německým pohořím, kde se čarodějnická mytologie potkává s hrázděnými městy UNESCO a serpentinami mezi přehradami. Z Wernigerode se stoupá lesy k Torfhausu s výhledem na bájný Brocken, přes císařský Goslar se vrátíte do hor k přehradě Rappbode s nejdelším visutým mostem pro pěší v Německu a divokým kaňonem Bodetal k Thale. Silnice v Harzu jsou zatáčkovité a rytmické, hlavně úseky přes Braunlage a údolím Bode. Nejlépe od května do října; v horských partiích počítejte s náhlou mlhou a vlhkou vozovkou pod stromy, o víkendech s vyšší koncentrací motorek a kontrolami. Kulturní tečkou je Quedlinburg s více než tisícovkou hrázděných domů.', 'loop', 185, 250, 'medium',
     '[{"lat": 51.83056, "lng": 10.79333, "label": "Start: Wernigerode"}, {"lat": 51.80139, "lng": 10.53417, "label": "Torfhaus"}, {"lat": 51.90639, "lng": 10.42917, "label": "Goslar"}, {"lat": 51.73972, "lng": 10.8925, "label": "Přehrada Rappbode"}, {"lat": 51.72528, "lng": 11.02722, "label": "Thale – Bodetal"}, {"lat": 51.78972, "lng": 11.14083, "label": "Quedlinburg"}, {"lat": 51.83056, "lng": 10.79333, "label": "Cíl: Wernigerode"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=51.83056,10.79333&destination=51.83056,10.79333&travelmode=driving&waypoints=51.80139,10.53417%7C51.90639,10.42917%7C51.73972,10.8925%7C51.72528,11.02722%7C51.78972,11.14083', 'https://commons.wikimedia.org/wiki/Special:FilePath/KLG%200541%20Schloss%20Wernigerode.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/KLG%200541%20Schloss%20Wernigerode.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Brocken-Gipfel.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Goslar%20Marktplatz.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rappbodetalsperre,Harz,%20DDR%20May%201990%20(5108131203).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pano%20blick%20vom%20hexentanzplatz%20ins%20bodetal%20ds%20wv%2005%202012.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Altstadt%20Quedlinburg%20von%20oben%20gesehen.%20IMG%201401WI.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rathaus%20Wernigerode.JPG"}'::text[], '{"Zámek Wernigerode","Brocken a vyhlídka Torfhaus","Goslar (UNESCO)","Přehrada Rappbode a most Titan RT","Bodetal a Hexentanzplatz (Thale)","Quedlinburg (UNESCO)","Restaurace: Brauhaus Wernigerode"}'::text[], '{"DE"}'::text[], false, 3440, 'approved');

  -- Romantická cesta – Würzburg, Rothenburg a Nördlingen
  delete from public.routes where name = 'Romantická cesta – Würzburg, Rothenburg a Nördlingen' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Romantická cesta – Würzburg, Rothenburg a Nördlingen', 'Severní a střední část nejslavnější německé turistické silnice od barokního Würzburgu údolím řeky Tauber až do měst v meteoritickém kráteru Ries. Jede se převážně po klidných okreskách mezi vinicemi, poli a hrázděnými městečky — žádné náročné pasáže, zato nekonečné střídání panoramat a historie. Perlami jsou středověký Rothenburg ob der Tauber s ikonickým zákoutím Plönlein, hradbami obehnaný Dinkelsbühl a Nördlingen, po jehož hradbách se dá obejít celé město. Trasa je ideální jako první etapa vícedenního výletu na jih; jezdit lze od jara do podzimu. Pozor na turistický ruch v centrech měst a na zóny s omezením vjezdu — motorku nechte na záchytných parkovištích u bran.', 'poi', 185, 240, 'easy',
     '[{"lat": 49.7925, "lng": 9.93917, "label": "Start: Würzburg"}, {"lat": 49.49056, "lng": 9.775, "label": "Bad Mergentheim"}, {"lat": 49.47889, "lng": 9.89944, "label": "Weikersheim"}, {"lat": 49.37444, "lng": 10.17889, "label": "Rothenburg ob der Tauber"}, {"lat": 49.07028, "lng": 10.31944, "label": "Dinkelsbühl"}, {"lat": 48.85167, "lng": 10.48861, "label": "Nördlingen"}, {"lat": 48.78639, "lng": 10.69028, "label": "Cíl: Harburg"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.7925,9.93917&destination=48.78639,10.69028&travelmode=driving&waypoints=49.49056,9.775%7C49.47889,9.89944%7C49.37444,10.17889%7C49.07028,10.31944%7C48.85167,10.48861', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pl%C3%B6nlein%20Rothenburg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Residenz%20W%C3%BCrzburg,%20S%C3%BCdfront,%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/DHBW%20Bad%20Mergentheim%20Schloss%202021.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20und%20Park%20Weikersheim.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pl%C3%B6nlein%20Rothenburg.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pl%C3%B6nlein,%20Rothenburg%20ob%20der%20Tauber,%20Alemania,%202023-06-17,%20DD%2036.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dinkelsbuehl%20Kirchturm%20West.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20of%20N%C3%B6rdlingen%20from%20St.%20Georgskirche%20-%202.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Harburg%20in%20Schwaben,%20Burg%2020170826%20001.jpg"}'::text[], '{"Würzburg – Rezidence (UNESCO)","Bad Mergentheim – zámek řádu německých rytířů","Zámek Weikersheim","Rothenburg ob der Tauber – Plönlein","Restaurace: Zur Höll (Rothenburg ob der Tauber)","Dinkelsbühl","Nördlingen – město v kráteru","Hrad Harburg"}'::text[], '{"DE"}'::text[], false, 3450, 'approved');

  -- Allgäu – Riedbergpass a Jochpass
  delete from public.routes where name = 'Allgäu – Riedbergpass a Jochpass' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Allgäu – Riedbergpass a Jochpass', 'Kompaktní alpský okruh západním Allgäu spojuje dva nejlepší německé průsmyky: Riedbergpass, nejvýše položenou zpevněnou silnici přes průsmyk v Německu (1407 m) se sklonem až 16 procent, a Jochpass u Oberjochu, jehož 106 zatáček z něj dělá nejzatáčkovitější silnici v zemi. Mezi nimi se jede zeleným údolím Illeru kolem horských vesnic s alpskou kulisou Nebelhornu a Hochvogelu. Zastávky lákají k pěší vložce — soutěska Breitachklamm patří k nejhlubším ve střední Evropě. Sezóna je od pozdního jara do října, Riedbergpass může být brzy na jaře a na podzim uzavřený nebo namrzlý; o víkendech jsou oba průsmyky plné motorek a na Jochpassu platí úsekové měření. Náročností je okruh ideální na protažení po dálničním přesunu z Česka.', 'loop', 135, 210, 'medium',
     '[{"lat": 47.5591, "lng": 10.2124, "label": "Start: Immenstadt im Allgäu"}, {"lat": 47.455, "lng": 10.13, "label": "Riedbergpass"}, {"lat": 47.40972, "lng": 10.27917, "label": "Oberstdorf"}, {"lat": 47.45611, "lng": 10.37278, "label": "Bad Hindelang"}, {"lat": 47.515, "lng": 10.40917, "label": "Oberjoch – Jochpass"}, {"lat": 47.5591, "lng": 10.2124, "label": "Cíl: Immenstadt im Allgäu"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=47.5591,10.2124&destination=47.5591,10.2124&travelmode=driving&waypoints=47.455,10.13%7C47.40972,10.27917%7C47.45611,10.37278%7C47.515,10.40917', 'https://commons.wikimedia.org/wiki/Special:FilePath/Riedbergpass%2016.09.2013.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grosser%20Alpsee%20bei%20Immenstadt.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Riedbergpass%2016.09.2013.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Breitachklamm.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Oberstdorf%20Panorama.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Oberstdorf%20Panorama.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bad%20Hindelang%20panorama%20view%20from%20south.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Oberjoch,%20Oberes%20Dorf%20mit%20Alpenklinik%20Santa%20Maria.jpg"}'::text[], '{"Velký Alpsee u Immenstadtu","Riedbergpass","Soutěska Breitachklamm","Oberstdorf","Restaurace: Zum Wilde Männle (Oberstdorf)","Bad Hindelang","Oberjoch – Jochpass"}'::text[], '{"DE"}'::text[], false, 3460, 'approved');

  -- Jižní Schwarzwald – Feldberg a Titisee
  delete from public.routes where name = 'Jižní Schwarzwald – Feldberg a Titisee' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Jižní Schwarzwald – Feldberg a Titisee', 'Okruh nejvyšší částí Černého lesa, který doplňuje slavnou severní B500 o divočejší a zatáčkovitější jih. Z Freiburgu se stoupá po bývalé závodní trati na Schauinsland — serpentiny, kde se od roku 1923 jezdily legendární závody do vrchu, jsou dodnes motorkářský rituál. Pokračuje se přes vodopád v Todtnau pod nejvyšší horu Feldberg a kolem jezer Titisee a Schluchsee, zpátky pak kaňonem Höllental, Pekelným údolím, kolem skály Hirschsprung. Kombinace rychlých horských pasáží, jezer na koupání a černoleských statků s kukačkami je ideální na celý den. Nejlépe květen až říjen; pozor na cyklisty na Schauinslandu, víkendové kontroly na B500 u Feldbergu a mokrou vozovku ve stínu smrků.', 'loop', 160, 240, 'medium',
     '[{"lat": 47.99556, "lng": 7.85222, "label": "Start: Freiburg im Breisgau"}, {"lat": 47.91194, "lng": 7.89861, "label": "Schauinsland"}, {"lat": 47.83167, "lng": 7.93083, "label": "Todtnau"}, {"lat": 47.87389, "lng": 8.00361, "label": "Feldberg"}, {"lat": 47.81806, "lng": 8.18056, "label": "Schluchsee"}, {"lat": 47.899, "lng": 8.156, "label": "Titisee"}, {"lat": 47.9204, "lng": 8.0854, "label": "Ravennaschlucht (Breitnau)"}, {"lat": 47.99556, "lng": 7.85222, "label": "Cíl: Freiburg im Breisgau"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=47.99556,7.85222&destination=47.99556,7.85222&travelmode=driving&waypoints=47.91194,7.89861%7C47.83167,7.93083%7C47.87389,8.00361%7C47.81806,8.18056%7C47.899,8.156%7C47.9204,8.0854', 'https://commons.wikimedia.org/wiki/Special:FilePath/Titisee-blick%20von%20hochfirst.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Freiburg%20-%20M%C3%BCnsterplatz.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Eugen%20Keidel%20Turm%20(Schauinsland)%20jm6719.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Todtnau%20Wasserfall.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/2012%20Schwarzwald%20101%20Feldberg%20Gipfel.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Schluchsee.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Titisee-blick%20von%20hochfirst.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ravenna%20Bridge.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ravenna%20Bridge.JPG"}'::text[], '{"Freiburg – Münsterplatz","Schauinsland – panoramatická silnice","Todtnauský vodopád","Feldberg","Schluchsee","Titisee","Höllental a Ravennský viadukt","Restaurace: Hofgut Sternen (Breitnau)"}'::text[], '{"DE"}'::text[], false, 3470, 'approved');

  -- Durynský les – Wartburg a Rennsteig
  delete from public.routes where name = 'Durynský les – Wartburg a Rennsteig' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Durynský les – Wartburg a Rennsteig', 'Okruh zeleným srdcem Německa podél legendárního hřebene Rennsteig, kudy po staletí vedla zemská stezka. Startuje se pod hradem Wartburg, kde Luther překládal Nový zákon, a pokračuje po zvlněných lesních silnicích přes horu Inselsberg do sportovního Oberhofu se skokanskými můstky. Zpáteční část vede přes hrázděné město Schmalkalden a nejvyšší vodopád Durynska v Trusetalu. Silnice jsou tu překvapivě prázdné, povrch po rekonstrukcích většinou výborný a rytmus zatáček plynulý — ideální okruh na půl až celý den. Nejlepší od května do října; v lesních úsecích pozor na zvěř za soumraku a na vlhko pod stromy, v zimě bývá hřeben dlouho pod sněhem.', 'loop', 150, 210, 'medium',
     '[{"lat": 50.97493, "lng": 10.31989, "label": "Start: Eisenach"}, {"lat": 50.955, "lng": 10.31694, "label": "Drachenschlucht"}, {"lat": 50.85139, "lng": 10.46639, "label": "Velký Inselsberg"}, {"lat": 50.70472, "lng": 10.72694, "label": "Oberhof"}, {"lat": 50.72083, "lng": 10.45194, "label": "Schmalkalden"}, {"lat": 50.79083, "lng": 10.41472, "label": "Trusetal"}, {"lat": 50.97493, "lng": 10.31989, "label": "Cíl: Eisenach"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.97493,10.31989&destination=50.97493,10.31989&travelmode=driving&waypoints=50.955,10.31694%7C50.85139,10.46639%7C50.70472,10.72694%7C50.72083,10.45194%7C50.79083,10.41472', 'https://commons.wikimedia.org/wiki/Special:FilePath/Die%20Wartburg%20bei%20Eisenach.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Die%20Wartburg%20bei%20Eisenach.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Eisenach%20Drachenschlucht%20001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Wechmar%20Inselsberg.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Schanzenanlage%20im%20Kanzlersgrund%20bei%20Oberhof.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Altstadt%20-%20Schmalkalden%20-%2020120408.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Auf%20der%20Teufelskanzel%20am%20Trusetaler%20Wasserfall%202H1A8928WI.jpg"}'::text[], '{"Wartburg (UNESCO)","Drachenschlucht","Velký Inselsberg","Oberhof – skokanské můstky","Schmalkalden","Trusetalský vodopád"}'::text[], '{"DE"}'::text[], false, 3480, 'approved');

  -- Rhön – Wasserkuppe a klášter Kreuzberg
  delete from public.routes where name = 'Rhön – Wasserkuppe a klášter Kreuzberg' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Rhön – Wasserkuppe a klášter Kreuzberg', 'Okruh krajem otevřených holých hřebenů, kterému se říká země dalekých výhledů — biosférická rezervace Rhön na pomezí tří spolkových zemí je jedním z nejoblíbenějších motorkářských revírů středního Německa. Hochrhönstraße se vlní po náhorních planinách bez lesa, takže výhledy nekončí; navíc je to od českých hranic co by kamenem dohodil. Trasa spojuje barokní Fuldu, památník studené války Point Alpha na bývalé hranici NDR, kolébku bezmotorového létání Wasserkuppe a klášterní pivovar na Kreuzbergu, kam si pro pivo jezdí půl Bavorska. Jarní a podzimní dny nabízejí nejčistší vzduch, v létě jsou hřebeny plné motorek. Pozor na silný vítr na otevřených úsecích, radary u Bischofsheimu a víkendová omezení na některých úsecích Hochrhönstraße.', 'loop', 165, 230, 'easy',
     '[{"lat": 50.55417, "lng": 9.67139, "label": "Start: Fulda"}, {"lat": 50.68528, "lng": 9.93167, "label": "Point Alpha (Geisa)"}, {"lat": 50.52167, "lng": 10.07417, "label": "Schwarzes Moor"}, {"lat": 50.37028, "lng": 9.97611, "label": "Klášter Kreuzberg"}, {"lat": 50.49806, "lng": 9.9375, "label": "Wasserkuppe"}, {"lat": 50.545, "lng": 9.89833, "label": "Milseburg"}, {"lat": 50.55417, "lng": 9.67139, "label": "Cíl: Fulda"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.55417,9.67139&destination=50.55417,9.67139&travelmode=driving&waypoints=50.68528,9.93167%7C50.52167,10.07417%7C50.37028,9.97611%7C50.49806,9.9375%7C50.545,9.89833', 'https://commons.wikimedia.org/wiki/Special:FilePath/Wasserkuppe%20Radom.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fulda%20-%20Dom%20-%20Panorama.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Geisa%20point%20alpha%20blick%20ulstertal%20ds%20wv%2030%2009%202011.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rh%C3%B6n%20schwarzes%20Moor.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rhoen%20Kloster%20Kreuzberg.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Wasserkuppe%20Radom.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Milseburg-Auersberg.JPG"}'::text[], '{"Fulda – barokní dóm","Point Alpha (Geisa)","Schwarzes Moor","Klášter Kreuzberg – klášterní pivovar","Wasserkuppe","Milseburg"}'::text[], '{"DE"}'::text[], false, 3490, 'approved');

  -- Švábská Alba – hrad Hohenzollern a údolí Dunaje
  delete from public.routes where name = 'Švábská Alba – hrad Hohenzollern a údolí Dunaje' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Švábská Alba – hrad Hohenzollern a údolí Dunaje', 'Velký okruh vápencovou vrchovinou jižního Německa, kde silnice neustále šplhají na náhorní plošinu a padají zpět do zaříznutých údolí — technicky nejzábavnější kraj mezi Stuttgartem a Bodamským jezerem. Trasa spojuje dva pohádkové hrady na skalách, Hohenzollern a Lichtenstein, s kaňonem horního Dunaje u Beuronu, který si nezadá s alpskými soutěskami. Cestou vodopád v Bad Urachu, hohenzollernská rezidence v Sigmaringenu a vyhlídka Knopfmacherfelsen vysoko nad řekou. Stovky metrů převýšení, vlásenky v zalesněných stráních a rychlé pasáže po plošině se střídají celý den. Nejlépe od dubna do října; pozor na vápencový štěrk po dešti, cyklisty v údolí Dunaje a víkendové kontroly na oblíbených stoupáních.', 'loop', 210, 290, 'medium',
     '[{"lat": 48.35172, "lng": 8.96317, "label": "Start: Hechingen"}, {"lat": 48.40639, "lng": 9.25778, "label": "Zámek Lichtenstein"}, {"lat": 48.48694, "lng": 9.37806, "label": "Bad Urach"}, {"lat": 48.08778, "lng": 9.21639, "label": "Sigmaringen"}, {"lat": 48.05, "lng": 8.96722, "label": "Beuron"}, {"lat": 48.35172, "lng": 8.96317, "label": "Cíl: Hechingen"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.35172,8.96317&destination=48.35172,8.96317&travelmode=driving&waypoints=48.40639,9.25778%7C48.48694,9.37806%7C48.08778,9.21639%7C48.05,8.96722', 'https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Hohenzollern%20-%206620-2.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Hohenzollern%20-%206620-2.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Lichtenstein%2004-2010.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Uracher%20Wasserfall.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Sigmaringen%202022.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Knopfmacherfelsen%20im%20Donautal.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kloster%20Beuron%202009%20Blick%20von%20Nordwesten.jpg"}'::text[], '{"Hrad Hohenzollern","Zámek Lichtenstein","Uracher Wasserfall (Bad Urach)","Zámek Sigmaringen","Knopfmacherfelsen","Klášter Beuron"}'::text[], '{"DE"}'::text[], false, 3500, 'approved');

