  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Nürburgring – Nordschleife', 'Nejslavnější závodní okruh světa, 20,8 km dlouhé Zelené peklo se 73 zatáčkami vinoucí se lesy Eifel. V termínech Touristenfahrten si můžete koupit kolo a projet legendární pasáže Karussell či Flugplatz na vlastní motorce. I bez jízdy stojí za zastávku muzeum ringu°werk a vyhlídky u trati, kde o víkendech duní vše od supersportů po historické stroje.', 50.3356, 6.9475, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nordschleife%20Pflanzgarten.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nordschleife%20Pflanzgarten.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Nordschleife%20Steilstrecke.jpg"}'::text[], 0),
    (v_route, 'Hrad Nürburg', 'Zřícenina hradu z 12. století na čedičovém kuželu přímo uprostřed okruhu, který kolem ní obtáčí své smyčky. Z věže je nejlepší výhled na Nordschleife i na zvlněnou krajinu Eifel — za jasného dne dohlédnete desítky kilometrů. Krátká procházka od parkoviště, ideální pauza mezi jízdami.', 50.33917, 6.93944, 'https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%BCrburg%20(Burg)%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%BCrburg%20(Burg)%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%BCrburg.JPG"}'::text[], 1),
    (v_route, 'Hohe Acht', 'Nejvyšší hora pohoří Eifel (747 m) s kamennou rozhlednou Kaiser-Wilhelm-Turm na vrcholu. Vede k ní krásně zvlněná silnička s rychlými táhlými oblouky, oblíbená mezi místními motorkáři. Z ochozu věže přehlédnete celý Nürburgring i sopečné kužely v okolí.', 50.38528, 7.00722, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kaiser-Wilhelm-Turm%20(Hohe%20Acht).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kaiser-Wilhelm-Turm%20(Hohe%20Acht).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hohe%20Acht.JPG"}'::text[], 2),
    (v_route, 'Klášter Maria Laach', 'Šestivěžová románská bazilika benediktinského opatství z 11. století patří k nejkrásnějším románským stavbám Německa. Klášter leží na břehu Laacher See — jezera v obří sopečné kaldeře, kde dodnes ze dna probublává oxid uhličitý. Klášterní zahradnictví a kavárna zvou k odpočinku u vody.', 50.40222, 7.25194, 'https://commons.wikimedia.org/wiki/Special:FilePath/00%200447%20Abtei%20Maria%20Laach%20-%20Deutschland.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/00%200447%20Abtei%20Maria%20Laach%20-%20Deutschland.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/00%200439%20Abtei%20Maria%20Laach%20-%20Deutschland.jpg"}'::text[], 3),
    (v_route, 'Weinfelder Maar (Daun)', 'Tajemné kruhové jezero zvané též Totenmaar — Mrtvé maary — je zatopený sopečný kráter u městečka Daun, obklopený dalšími dvěma maary na dohled. Silnička mezi nimi patří k nejhezčím úsekům Vulkaneifel, samé krátké zatáčky a výhledy do kráterů. Na hraně kráteru stojí osamělá kaple, k jezeru vede pěšina na krátkou procházku.', 50.17722, 6.85056, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dauner%20Maare,%20Weinfelder%20Maar%20oder%20Totenmaar.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dauner%20Maare,%20Weinfelder%20Maar%20oder%20Totenmaar.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Totenmaar%20weinfelder%20maar%20eifel.jpg"}'::text[], 4),
    (v_route, 'Manderscheid – hradní dvojice', 'Dva středověké hrady, Oberburg a Niederburg, stojí proti sobě na skalních ostrozích nad hlubokým údolím říčky Lieser. Serpentiny, které mezi nimi klesají a stoupají, jsou malým motorkářským bonbónkem na závěr okruhu. Z vyhlídky Kaisertempelchen je nejlepší pohled na oba hrady najednou.', 50.09556, 6.80972, 'https://commons.wikimedia.org/wiki/Special:FilePath/Oberburg%20und%20Niederburg%20in%20Manderscheid.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Oberburg%20und%20Niederburg%20in%20Manderscheid.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/NiederburgManderscheid.jpg"}'::text[], 5),
    (v_route, 'Restaurace: Pistenklause (Nürburg)', 'Kultovní podnik přímo pod hradem Nürburg, kde se už desítky let potkávají závodníci, testovací jezdci i motorkáři z celého světa — stěny jsou obsypané podpisy slavných pilotů. Specialitou jsou steaky servírované na rozpáleném lávovém kameni, na kterém si maso dopékáte sami. Rezervace se o víkendech vyplatí, podnik bývá plný.', 50.33389, 6.945, 'https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%BCrburg%20(Burg)%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%BCrburg%20(Burg)%2001.jpg"}'::text[], 6);
