  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Cochem – Reichsburg', 'Novogoticky přestavěný říšský hrad na kuželovitém kopci nad Cochemem je symbolem celé Mosely. Pod ním se krčí malebné městečko s hrázděným náměstím, promenádou a desítkami vinoték. Motorky pohodlně zaparkujete u řeky a na hrad dojdete pěšky za deset minut.', 50.14472, 7.16833, 'https://commons.wikimedia.org/wiki/Special:FilePath/Reichsburg%20Cochem.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Reichsburg%20Cochem.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Reichsburg%20Cochem%20at%20Moselle.jpg"}'::text[], 0),
    (v_route, 'Hrad Eltz', 'Nikdy nedobytý hrad z 12. století, ukrytý v hlubokém lesním údolí potoka Elzbach, patří k nejfotografovanějším místům Německa — zdobil i pětisetmarkovou bankovku. Přes 850 let jej vlastní stále stejný rod a interiéry s původním vybavením jsou přístupné. Od parkoviště vede k hradu příjemná lesní procházka, první pohled ze stezky bere dech.', 50.20542, 7.33619, 'https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Eltz%202005.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Eltz%202005.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Burg%20Eltz.jpg"}'::text[], 1),
    (v_route, 'Beilstein na Mosele', 'Miniaturní vinařské městečko přezdívané Spící kráska Mosely — pár uliček hrázděných domů sevřených mezi vinicemi, klášterním schodištěm a zříceninou hradu Metternich. Působí, jako by se tu zastavil čas, natáčely se tu i historické filmy. Ideální krátká zastávka na kávu u řeky.', 50.10972, 7.24083, 'https://commons.wikimedia.org/wiki/Special:FilePath/Beilstein%20BW%200.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Beilstein%20BW%200.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Beilstein%20(Mosel),%202012-08%20CN-01.jpg"}'::text[], 2),
    (v_route, 'Calmont – smyčka u Bremmu', 'Nejstrmější vinice Evropy se sklonem až 65 stupňů se zvedá nad dokonalou podkovou moselského meandru u obce Bremm. Z vyhlídky na hraně svahu se otevírá jeden z nejslavnějších pohledů na řeku — smyčka s vesničkou a vinicemi jako na dlani. Nahoru vede úzká silnička z náhorní plošiny, posledních pár metrů pěšky.', 50.10444, 7.11278, 'https://commons.wikimedia.org/wiki/Special:FilePath/Moselschleife%20bei%20Bremm.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Moselschleife%20bei%20Bremm.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Calmont-Klettersteig.jpg"}'::text[], 3),
    (v_route, 'Traben-Trarbach', 'Dvojměstí na obou březích Mosely proslulo kolem roku 1900 jako druhé největší centrum obchodu s vínem na světě — dodnes tu stojí honosné secesní vily vinařských dynastií a kilometry podzemních sklepů, které lze navštívit. Přes řeku vede elegantní most s branou Brückentor. Příjemné místo na oběd nebo ochutnávku ryzlinku.', 49.95083, 7.115, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20Traben-Trarbach%2002.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20Traben-Trarbach%2002.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Traben-Trarbach,%202012-08%20CN-01.jpg"}'::text[], 4),
    (v_route, 'Bernkastel-Kues', 'Vinařská metropole střední Mosely s jedním z nejkrásnějších hrázděných náměstí Německa a šikmým domečkem Spitzhäuschen z roku 1416. Nad městem trůní zřícenina Landshut s výhledem na moře vinic. Kolem náměstí desítky vinných stánků a kaváren — návrat do Cochemu po druhém břehu už je pak jen příjemné klouzání podél řeky.', 49.91611, 7.07639, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bernkastel-Kues%20Marktplatz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bernkastel-Kues%20Marktplatz.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Marktplatz%20in%20Bernkastel-Kues.JPG"}'::text[], 5),
    (v_route, 'Restaurace: Alte Thorschenke (Cochem)', 'Historický hostinec z roku 1332 v městské bráně Cochemu, jeden z nejstarších v Porýní. Poctivá německá kuchyně — pečeně, zvěřina a moselské speciality — k tomu vlastní vína z okolních strmých svahů. Skvělé zakončení okruhu pár kroků od promenády.', 50.1475, 7.1666, 'https://commons.wikimedia.org/wiki/Special:FilePath/Reichsburg%20Cochem%20at%20Moselle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Reichsburg%20Cochem%20at%20Moselle.jpg"}'::text[], 6);
  insert into public.routes
