  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Koblenz – Deutsches Eck', 'Slavný Německý roh — ostroh na soutoku Rýna a Mosely s monumentální jezdeckou sochou císaře Viléma I. Nad ním se tyčí pevnost Ehrenbreitstein, kam vede lanovka přes Rýn s parádním výhledem na soutok. Ideální startovní bod okruhu s velkým parkovištěm u promenády.', 50.36444, 7.60583, 'https://commons.wikimedia.org/wiki/Special:FilePath/Deutsches%20Eck%20Koblenz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Deutsches%20Eck%20Koblenz.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Koblenz%20Deutsches%20Eck.JPG"}'::text[], 0),
    (v_route, 'Marksburg', 'Jediný výšinný hrad na středním Rýnu, který nebyl nikdy dobyt ani zničen — díky tomu nabízí autenticky zachovalý středověk včetně zbrojnice a hradní kuchyně. Stojí na kuželu nad městečkem Braubach a serpentina k hradnímu parkovišti je příjemná rozcvička. Prohlídky probíhají denně s průvodcem.', 50.2725, 7.64889, 'https://commons.wikimedia.org/wiki/Special:FilePath/Marksburg-Braubach.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Marksburg-Braubach.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Marksburg.jpg"}'::text[], 1),
    (v_route, 'Skála Loreley', 'Bájná břidlicová skála 132 metrů nad nejužším a nejnebezpečnějším místem Rýna, kde podle legendy zpěv krásné Loreley lákal lodníky do záhuby. Nahoře je moderní vyhlídková plošina a kulturní areál; výjezd serpentinami od St. Goarshausenu je krátký a zábavný. Pohled na říční zákrutu s hradem Katz patří k ikonám Německa.', 50.13944, 7.72889, 'https://commons.wikimedia.org/wiki/Special:FilePath/Loreley%202025.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Loreley%202025.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Loreley%20am%20Rhein.JPG"}'::text[], 2),
    (v_route, 'Niederwalddenkmal (Rüdesheim)', 'Kolosální pomník Germanie nad vinicemi Rüdesheimu, postavený po sjednocení Německa v roce 1871, s širokým rozhledem na soutok Rýna a Nahe. Dolů do městečka se slavnou uličkou Drosselgasse to je pár minut. Odtud přívozem přes řeku do Bingenu a zpět na levobřežní B9.', 49.9875, 7.89083, 'https://commons.wikimedia.org/wiki/Special:FilePath/Germania%20-%20Niederwalddenkmal.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Germania%20-%20Niederwalddenkmal.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/MK9952%20Niederwalddenkmal.jpg"}'::text[], 3),
    (v_route, 'Bacharach', 'Snad nejromantičtější vinařské městečko na Rýnu — kompletní hradby, hrázděné uličky, gotická kaple Wernerkapelle a nad tím vším hrad Stahleck, dnes hostel. Victor Hugo o něm psal jako o nejkrásnějším místě na Rýně. Krátká procházka po hradbách nabízí výhledy na vinice i řeku.', 50.05861, 7.76917, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bacharach%20(Rhein)%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bacharach%20(Rhein)%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bacharach%20from%20the%20Postenturm.jpg"}'::text[], 4),
    (v_route, 'Hrad Rheinfels (St. Goar)', 'Kdysi největší pevnost na Rýně, jejíž rozsáhlé ruiny s podzemními chodbami se dají prozkoumávat celé hodiny. Z bastionů je přímý výhled přes řeku na hrady Katz a Maus i na skálu Loreley. Na hrad vyjedete krátkou strmou silničkou přímo z St. Goaru.', 50.15389, 7.70528, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ausblick%20von%20der%20Burg%20Rheinfels%20auf%20Sankt%20Goar%20und%20Sankt%20Goarshausen%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ausblick%20von%20der%20Burg%20Rheinfels%20auf%20Sankt%20Goar%20und%20Sankt%20Goarshausen%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Rheinfels-03-Hohe%20Batterie.jpg"}'::text[], 5),
    (v_route, 'Boppard – rýnská smyčka', 'Lázeňské město s římskými hradbami a nejdelší rýnskou promenádou leží u největšího meandru řeky. Z vyhlídky Vierseenblick nad městem vypadá Rýn díky zákrutám jako čtyři oddělená jezera — nahoru vede sedačková lanovka nebo pěší stezka. Příjemné korzo na kávu před posledním úsekem do Koblenze.', 50.23139, 7.59083, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rheinschleife-Boppard.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rheinschleife-Boppard.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Boppard%20-%20Kloster%20Marienberg%20-%20panoramio.jpg"}'::text[], 6),
    (v_route, 'Restaurace: Weinhaus Heilig Grab (Boppard)', 'Nejstarší vinný šenk v Boppardu s více než dvousetletou tradicí, útulným dvorkem pod kaštany a vlastními ryzlinky z okolních svahů. K vínu se podávají poctivé regionální speciality — flammkuchen, sýry a domácí paštiky. Oblíbená zastávka místních i projíždějících motorkářů.', 50.2326, 7.5862, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rheinschleife-Boppard.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rheinschleife-Boppard.jpg"}'::text[], 7);
  insert into public.routes
