  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zámek Wernigerode', 'Pohádkový novogotický zámek na kopci nad barevným hrázděným městem, kterému se říká Neuschwanstein severu. Interiéry šlechtického rodu Stolbergů jsou přístupné a z teras je výhled až k Brockenu. Dole ve městě stojí za zastávku křivá radnice, jedna z nejfotografovanějších v Německu.', 51.83056, 10.79333, 'https://commons.wikimedia.org/wiki/Special:FilePath/KLG%200541%20Schloss%20Wernigerode.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/KLG%200541%20Schloss%20Wernigerode.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Wernigerode%20Luftbild%202.jpg"}'::text[], 0),
    (v_route, 'Brocken a vyhlídka Torfhaus', 'Nejvyšší hora Harzu (1141 m), opředená čarodějnickými pověstmi z Goethova Fausta — na vrchol nesmí motorová vozidla, ale z Torfhausu na trase je na Brocken nejslavnější výhled. Kolem vede zábavná horská silnice B4 s dlouhými oblouky lesem. Kdo má čas, může na vrchol vyjet historickou parní úzkokolejkou z Wernigerode.', 51.80139, 10.53417, 'https://commons.wikimedia.org/wiki/Special:FilePath/Brocken-Gipfel.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Brocken-Gipfel.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Aussicht%20Brocken%20Harz.JPG"}'::text[], 1),
    (v_route, 'Goslar (UNESCO)', 'Tisícileté císařské město na úpatí Harzu s románskou falcí, kostely a stovkami hrázděných domů zapsanými na seznamu UNESCO společně s historickým dolem Rammelsberg. Náměstí s bronzovou kašnou a zvonkohrou je ideální na dopolední kávu. Z Goslaru se vracíte do hor přes serpentiny u Hahnenklee.', 51.90639, 10.42917, 'https://commons.wikimedia.org/wiki/Special:FilePath/Goslar%20Marktplatz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Goslar%20Marktplatz.jpg"}'::text[], 2),
    (v_route, 'Přehrada Rappbode a most Titan RT', 'Nejvyšší přehradní hráz Německa (106 m) zadržuje vodu v hlubokém zalesněném údolí a přímo vedle ní se klene Titan RT — 458 metrů dlouhý visutý most pro pěší, jeden z nejdelších na světě. Adrenalinoví nadšenci tu najdou i obří houpačku a zipline přes údolí. Silnice kolem přehradních jezer patří k nejhezčím v Harzu.', 51.73972, 10.8925, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rappbodetalsperre,Harz,%20DDR%20May%201990%20(5108131203).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rappbodetalsperre,Harz,%20DDR%20May%201990%20(5108131203).jpg"}'::text[], 3),
    (v_route, 'Bodetal a Hexentanzplatz (Thale)', 'Nejhlubší skalní kaňon severního Německa, kterým se řeka Bode prodírá mezi žulovými stěnami k Thale. Nad údolím leží legendární Čarodějnický taneční plac Hexentanzplatz s vyhlídkami do soutěsky — nahoru vede silnička plná vlásenek nebo kabinová lanovka. Naproti přes údolí se tyčí skála Rosstrappe s otiskem kopyta bájného koně.', 51.72528, 11.02722, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pano%20blick%20vom%20hexentanzplatz%20ins%20bodetal%20ds%20wv%2005%202012.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pano%20blick%20vom%20hexentanzplatz%20ins%20bodetal%20ds%20wv%2005%202012.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rosstrappe%20Bodetal%201900.jpg"}'::text[], 4),
    (v_route, 'Quedlinburg (UNESCO)', 'Přes 1300 hrázděných domů z osmi století dělá z Quedlinburgu největší památkovou rezervaci svého druhu v Německu. Nad městem se zvedá Zámecký vrch s románskou kolegiátní bazilikou, kde byl pohřben první německý král Jindřich Ptáčník. Uličky kolem náměstí zvou na zmrzlinu a procházku před návratem do Wernigerode.', 51.78972, 11.14083, 'https://commons.wikimedia.org/wiki/Special:FilePath/Altstadt%20Quedlinburg%20von%20oben%20gesehen.%20IMG%201401WI.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Altstadt%20Quedlinburg%20von%20oben%20gesehen.%20IMG%201401WI.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Quedlinburg%20Markt.JPG"}'::text[], 5),
    (v_route, 'Restaurace: Brauhaus Wernigerode', 'Městský pivovar s restaurací pár kroků od křivé radnice vaří nefiltrovaný Hasseröder styl piv přímo za výčepem a k tomu servíruje harcké speciality — pečená kolena, klobásy a sezónní zvěřinu. Velké porce, férové ceny a výborné hodnocení. Ideální večerní tečka za okruhem (nealko pivo pro jezdce samozřejmostí).', 51.835, 10.78528, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rathaus%20Wernigerode.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rathaus%20Wernigerode.JPG"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Würzburg – Rezidence (UNESCO)', 'Barokní rezidence knížecích biskupů, památka UNESCO s největší stropní freskou světa od Tiepola nad monumentálním schodištěm. Kolem se rozkládají dvorní zahrady a přes řeku Mohan shlíží pevnost Marienberg nad vinicemi. Skvělé místo, kde před vyjížďkou nasát atmosféru franckého vinařského kraje.', 49.7925, 9.93917, 'https://commons.wikimedia.org/wiki/Special:FilePath/Residenz%20W%C3%BCrzburg,%20S%C3%BCdfront,%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Residenz%20W%C3%BCrzburg,%20S%C3%BCdfront,%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Wuerzburger%20Residenz%20vom%20Hofgarten.jpg"}'::text[], 0),
    (v_route, 'Bad Mergentheim – zámek řádu německých rytířů', 'Lázeňské město v údolí Tauberu bylo přes 300 let sídlem velmistrů Řádu německých rytířů — jejich renesančně-barokní zámek s muzeem dominuje centru dodnes. Cesta sem vede malebným údolím Tauberu po části slavné cyklostezky a vinařské silnice. Příjemné korzo s kavárnami na náměstí.', 49.49056, 9.775, 'https://commons.wikimedia.org/wiki/Special:FilePath/DHBW%20Bad%20Mergentheim%20Schloss%202021.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/DHBW%20Bad%20Mergentheim%20Schloss%202021.jpg"}'::text[], 1),
    (v_route, 'Zámek Weikersheim', 'Renesanční perla rodu Hohenlohe s proslulým Rytířským sálem s kazetovým stropem a jednou z nejkrásnějších barokních zahrad Německa, lemovanou galerií trpaslíků. Zámek leží přímo na Romantické cestě v tichém vinařském městečku. Zahrada s oranžerií je ideální na krátkou procházku mezi etapami.', 49.47889, 9.89944, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20und%20Park%20Weikersheim.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20und%20Park%20Weikersheim.jpg"}'::text[], 2),
    (v_route, 'Rothenburg ob der Tauber – Plönlein', 'Nejzachovalejší středověké město Německa s kompletním prstencem hradeb a světoznámým zákoutím Plönlein — šikmý hrázděný domek mezi dvěma věžemi je jedním z nejfotografovanějších motivů Evropy. Projděte si hradební ochoz a náměstí s radnicí, z jejíž věže je výhled na moře červených střech. Motorku nechte na parkovišti P1 u hradeb, centrum je pěší zónou.', 49.37444, 10.17889, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pl%C3%B6nlein%20Rothenburg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pl%C3%B6nlein%20Rothenburg.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pl%C3%B6nlein,%20Rothenburg%20ob%20der%20Tauber,%20Alemania,%202023-06-17,%20DD%2036.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Zur Höll (Rothenburg ob der Tauber)', 'Vinárna a hospůdka V pekle sídlí v nejstarším domě Rothenburgu z 10. století — kamenné zdi, svíčky a pár stolů vytvářejí nezapomenutelnou atmosféru. Podávají francká vína a jednoduchá poctivá jídla jako domácí sulc, klobásy či sýrové variace. Večer bývá plno, přijďte dřív nebo rezervujte.', 49.3769, 10.178, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pl%C3%B6nlein,%20Rothenburg%20ob%20der%20Tauber,%20Alemania,%202023-06-17,%20DD%2036.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pl%C3%B6nlein,%20Rothenburg%20ob%20der%20Tauber,%20Alemania,%202023-06-17,%20DD%2036.jpg"}'::text[], 4),
    (v_route, 'Dinkelsbühl', 'Hradbami sevřené městečko, které přežilo třicetiletou válku i druhou světovou bez úhony — barevné štítové domy kolem kostela sv. Jiří vypadají jako kulisy. Na rozdíl od Rothenburgu je tu znatelně méně turistů a atmosféra klidnější. Věže hradeb se odrážejí v rybnících kolem města, ideální foto zastávka.', 49.07028, 10.31944, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dinkelsbuehl%20Kirchturm%20West.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dinkelsbuehl%20Kirchturm%20West.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/W%C3%B6rnitz%20Dinkelsb%C3%BChl%2001.JPG"}'::text[], 5),
    (v_route, 'Nördlingen – město v kráteru', 'Jediné město Německa s kompletně pochozími hradbami leží uprostřed kráteru Ries, který před 15 miliony let vyhloubil meteorit o průměru přes kilometr. Z 90 metrů vysoké věže Daniel kostela sv. Jiří je kruhový tvar města i kráteru krásně vidět; kámen suevit, z něhož je kostel postaven, vznikl právě při dopadu. Geologické muzeum RiesKraterMuseum vysvětlí celou událost.', 48.85167, 10.48861, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20of%20N%C3%B6rdlingen%20from%20St.%20Georgskirche%20-%202.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20of%20N%C3%B6rdlingen%20from%20St.%20Georgskirche%20-%202.jpg"}'::text[], 6),
    (v_route, 'Hrad Harburg', 'Mohutný štaufský hrad z 11. století, jeden z nejzachovalejších v jižním Německu, se rozkládá na hřebeni nad údolím řeky Wörnitz a stejnojmenným městečkem. Nádvoří, ochozy a věže jsou přístupné, z hradeb je výhled na klikatící se řeku. Důstojná tečka za etapou Romantické cesty — odtud je to kousek do Donauwörthu na Dunaji.', 48.78639, 10.69028, 'https://commons.wikimedia.org/wiki/Special:FilePath/Harburg%20in%20Schwaben,%20Burg%2020170826%20001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Harburg%20in%20Schwaben,%20Burg%2020170826%20001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Harburg%20Schwaben%20BW%206.JPG"}'::text[], 7);
