  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Velký Alpsee u Immenstadtu', 'Největší přírodní jezero Allgäu se táhne tři kilometry mezi zelenými hřebeny Nagelfluhkette. Silnice po severním břehu nabízí nejhezčí výhledy na hladinu s plachetnicemi a horskou kulisu. U jezera jsou pláže a kiosky, ráno tu bývá božský klid.', 47.56972, 10.17167, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grosser%20Alpsee%20bei%20Immenstadt.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grosser%20Alpsee%20bei%20Immenstadt.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Gro%C3%9Fer%20Alpsee%2003.jpg"}'::text[], 0),
    (v_route, 'Riedbergpass', 'Nejvýše položený silniční průsmyk Německa (1407 m) překonává hřeben mezi údolím Illeru a zapadlým Balderschwangem u rakouských hranic. Stoupání se sklonem až 16 procent, vlásenky nad hranicí lesa a výhled na Vysoký Ifen — malé alpské divadlo v kapesním vydání. Na vrcholu je parkoviště, odkud to je pár kroků k vyhlídce.', 47.455, 10.13, 'https://commons.wikimedia.org/wiki/Special:FilePath/Riedbergpass%2016.09.2013.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Riedbergpass%2016.09.2013.JPG"}'::text[], 1),
    (v_route, 'Soutěska Breitachklamm', 'Jedna z nejhlubších a nejpůsobivějších skalních soutěsek střední Evropy — řeka Breitach se tu zařezává až 150 metrů hluboko do vápence. Zavěšené lávky vedou přímo nad hučící vodou mezi převislými stěnami, procházka tam a zpět zabere hodinku. Přilbu a bundu nechte v kufru, v soutěsce z okolních stěn kape voda.', 47.38722, 10.245, 'https://commons.wikimedia.org/wiki/Special:FilePath/Breitachklamm.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Breitachklamm.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Breitachklamm-eingang01.jpg"}'::text[], 2),
    (v_route, 'Oberstdorf', 'Nejjižnější město Německa a slavné středisko zimních sportů se skokanskými můstky Čtyř můstkových turné, obklopené dvoutisícovkami Allgäuských Alp. Centrum s pěší zónou žije po celý rok, lanovka na Nebelhorn vyveze za pár minut do výšky 2224 m s výhledem na 400 vrcholů. Dobré místo na delší pauzu uprostřed okruhu.', 47.40972, 10.27917, 'https://commons.wikimedia.org/wiki/Special:FilePath/Oberstdorf%20Panorama.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Oberstdorf%20Panorama.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Zum Wilde Männle (Oberstdorf)', 'Tradiční allgäuská hospoda v centru Oberstdorfu s dřevěným interiérem a poctivou horskou kuchyní — käsespätzle z místních sýrů, telecí řízek nebo pečeně s knedlíkem. Dlouhodobě výborně hodnocený podnik oblíbený u místních i hostů. Po Breitachklammu a Riedbergpassu zasloužená energie na druhou půlku okruhu.', 47.4093, 10.2795, 'https://commons.wikimedia.org/wiki/Special:FilePath/Oberstdorf%20Panorama.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Oberstdorf%20Panorama.jpg"}'::text[], 4),
    (v_route, 'Bad Hindelang', 'Klimatické lázně na úpatí Jochpassu s barokním kostelem a horskou kulisou údolí Ostrachtal, odkud startuje slavné stoupání do Oberjochu. Vesnice je známá ekologickým hospodařením — polovina území patří do chráněných oblastí a na loukách se pasou stáda na tradičním horském odchovu. Ideální zastávka na doplnění vody před zatáčkovými hody.', 47.45611, 10.37278, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bad%20Hindelang%20panorama%20view%20from%20south.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bad%20Hindelang%20panorama%20view%20from%20south.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bad%20Hindelang%2002.jpg"}'::text[], 5),
    (v_route, 'Oberjoch – Jochpass', 'Sto šest zatáček na sedmi kilometrech dělá z Jochpassstraße nejzatáčkovitější silnici Německa — plynulé, přehledné vlásenky stoupají z Bad Hindelangu do horské vsi Oberjoch v 1136 metrech. Z vyhlídky Kanzel v půlce stoupání je výhled na celé údolí Ostrachu. Pozor na úsekové měření rychlosti a víkendový provoz, zatáčky lákají k lehkomyslnosti.', 47.515, 10.40917, 'https://commons.wikimedia.org/wiki/Special:FilePath/Oberjoch,%20Oberes%20Dorf%20mit%20Alpenklinik%20Santa%20Maria.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Oberjoch,%20Oberes%20Dorf%20mit%20Alpenklinik%20Santa%20Maria.jpg"}'::text[], 6);
