  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Freiburg – Münsterplatz', 'Slunečná metropole Černého lesa s gotickým münsterem, jehož 116metrová prolamovaná věž je označována za nejkrásnější věž křesťanstva. Kolem katedrály denně (kromě neděle) probíhá trh s regionálními dobrotami a městem protékají známé stružky Bächle. Odtud se startuje rovnou do serpentin na Schauinsland.', 47.99556, 7.85222, 'https://commons.wikimedia.org/wiki/Special:FilePath/Freiburg%20-%20M%C3%BCnsterplatz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Freiburg%20-%20M%C3%BCnsterplatz.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Freiburger%20M%C3%BCnster.jpg"}'::text[], 0),
    (v_route, 'Schauinsland – panoramatická silnice', 'Domácí hora Freiburgu (1284 m), na kterou vede bývalá trať závodů do vrchu s dvanácti kilometry serpentin — dnes oblíbená vyhlídková silnice s omezením, které stojí za respektování. Z věže Eugen-Keidel-Turm na vrcholu dohlédnete přes Rýnský příkop až na Vogézy a při dobré dohlednosti na Alpy. U vrcholu je i návštěvnický důl a horská bouda s občerstvením.', 47.91194, 7.89861, 'https://commons.wikimedia.org/wiki/Special:FilePath/Eugen%20Keidel%20Turm%20(Schauinsland)%20jm6719.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Eugen%20Keidel%20Turm%20(Schauinsland)%20jm6719.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Schauinsland%20vom%20Feldberg.jpg"}'::text[], 1),
    (v_route, 'Todtnauský vodopád', 'Devadesát sedm metrů vysoký vodopád u Todtnau patří k nejvyšším přírodním vodopádům Německa — voda tu padá v několika stupních po žulových stěnách. Od parkoviště u silnice na Aftersteg je to k vyhlídkám krátká procházka lesem. Osvěžující pauza mezi Schauinslandem a Feldbergem.', 47.83167, 7.93083, 'https://commons.wikimedia.org/wiki/Special:FilePath/Todtnau%20Wasserfall.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Todtnau%20Wasserfall.jpg"}'::text[], 2),
    (v_route, 'Feldberg', 'Nejvyšší hora Německa mimo Alpy (1493 m) s holým vrcholovým hřebenem, odkud je za jasného počasí vidět řetěz alpských vrcholů od Säntisu po Mont Blanc. Silnice B317 přes sedlo Feldbergpass je nejvýše vedená spolková silnice v zemi. Od horního parkoviště vyjede na Seebuck sedačková lanovka, pěšky to je nahoru půlhodina.', 47.87389, 8.00361, 'https://commons.wikimedia.org/wiki/Special:FilePath/2012%20Schwarzwald%20101%20Feldberg%20Gipfel.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/2012%20Schwarzwald%20101%20Feldberg%20Gipfel.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Feldberg%20(Schwarzwald)%20Radarstation%20und%20Feldbergturm.JPG"}'::text[], 3),
    (v_route, 'Schluchsee', 'Největší jezero Černého lesa, přehradní nádrž v nadmořské výšce přes 900 metrů s průzračnou vodou a alpskou atmosférou. Silnice po severním břehu nabízí kilometry výhledů na hladinu; u hráze a v obci Schluchsee jsou pláže i restaurace. Klidnější a méně turistický protějšek slavnějšího Titisee.', 47.81806, 8.18056, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schluchsee.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schluchsee.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Schluchsee%20Bildstein.jpg"}'::text[], 4),
    (v_route, 'Titisee', 'Ledovcové jezero, u kterého tepe turistické srdce Černého lesa — promenáda s obchůdky s kukačkovými hodinami, šlapadla a výletní lodičky. Z vyhlídky na protějším Hochfirstu je jezero s horskou kulisou jako z pohlednice. V sezóně počítejte s davy; nejhezčí je brzy ráno nebo navečer.', 47.899, 8.156, 'https://commons.wikimedia.org/wiki/Special:FilePath/Titisee-blick%20von%20hochfirst.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Titisee-blick%20von%20hochfirst.jpg"}'::text[], 5),
    (v_route, 'Höllental a Ravennský viadukt', 'Pekelné údolí — divoký kaňon, kterým se B31 a železnice Höllentalbahn prodírají z hor k Freiburgu kolem skály Hirschsprung se sochou jelena, jenž prý soutěsku přeskočil. U Breitnau překračuje boční soutěsku Ravenna majestátní kamenný viadukt vysoký 37 metrů. Pod viaduktem je lávková stezka soutěskou s mlýnky a vodopády.', 47.9204, 8.0854, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ravenna%20Bridge.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ravenna%20Bridge.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Viadukt%20Ravennaschlucht%20mit%20Weihnachtsmarkt.jpg"}'::text[], 6),
    (v_route, 'Restaurace: Hofgut Sternen (Breitnau)', 'Historický zájezdní dvůr přímo pod Ravennským viaduktem, kde nocoval už Goethe i Marie Antoinetta cestou do Francie. Dnes areál s výborně hodnocenou restaurací černoleské kuchyně, sklárnou a pekárnou, kde pečou originální schwarzwaldský dort. Ideální oběd či káva na zpáteční cestě Höllentalem.', 47.92, 8.085, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ravenna%20Bridge.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ravenna%20Bridge.JPG"}'::text[], 7);
