  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Wartburg (UNESCO)', 'Nejslavnější hrad Německa na skále nad Eisenachem — zde překládal Martin Luther v přestrojení Nový zákon do němčiny a zde se podle pověsti konaly pěvecké souboje minnesängrů z Wagnerova Tannhäusera. Románský palác patří k nejzachovalejším severně od Alp a hrad je zapsán na seznamu UNESCO. Na parkoviště pod hradem vede pěkná lesní serpentina, zbytek pěšky nebo kyvadlovým busem.', 50.96639, 10.30667, 'https://commons.wikimedia.org/wiki/Special:FilePath/Die%20Wartburg%20bei%20Eisenach.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Die%20Wartburg%20bei%20Eisenach.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Thuringia%20Eisenach%20asv2020-07%20img23%20Wartburg%20Castle.jpg"}'::text[], 0),
    (v_route, 'Drachenschlucht', 'Dračí soutěska u Eisenachu je místy jen 70 centimetrů široká skalní chodba, kterou protéká potok pod kovovými rošty pěší stezky. Mechem obrostlé stěny a chladný vzduch z podzemí vytvářejí kulisu jak z fantasy filmu. Vstup je u silnice na Hohe Sonne, průchod soutěskou tam a zpět zabere necelou hodinu.', 50.955, 10.31694, 'https://commons.wikimedia.org/wiki/Special:FilePath/Eisenach%20Drachenschlucht%20001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Eisenach%20Drachenschlucht%20001.jpg"}'::text[], 1),
    (v_route, 'Velký Inselsberg', 'Výrazný kužel (916 m) vyčnívající z hřebene Rennsteigu, jeden z nejlepších rozhledových vrcholů Durynska — za dobré viditelnosti dohlédnete přes celý Durynský les. Až téměř na vrchol vede silnička ze sedla Grenzwiese, nahoře jsou dvě horské boudy s občerstvením. Stoupání od Tabarzu je oblíbený motorkářský úsek se sérií vlásenek.', 50.85139, 10.46639, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wechmar%20Inselsberg.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wechmar%20Inselsberg.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Blick%20vom%20Inselsberg%2001.JPG"}'::text[], 2),
    (v_route, 'Oberhof – skokanské můstky', 'Nejznámější zimní středisko bývalé NDR a dodnes centrum německého biatlonu a skoků na lyžích — moderní můstky v Kanzlersgrundu a biatlonová aréna se dají prohlédnout i v létě. Kolem Oberhofu vede Rennsteig a silnice přes hřeben patří k nejhezčím v pohoří. V městečku je dost restaurací na oběd.', 50.70472, 10.72694, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schanzenanlage%20im%20Kanzlersgrund%20bei%20Oberhof.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schanzenanlage%20im%20Kanzlersgrund%20bei%20Oberhof.jpg"}'::text[], 3),
    (v_route, 'Schmalkalden', 'Hrázděné městečko, které dalo jméno protestantskému Šmalkaldskému spolku — nad pastelovými uličkami se zvedá renesanční zámek Wilhelmsburg s dokonale zachovalou zámeckou kaplí. Historické jádro patří k nejucelenějším v Durynsku a je příjemně bez davů. Zastávka na kávu na náměstí Altmarkt stojí za to.', 50.72083, 10.45194, 'https://commons.wikimedia.org/wiki/Special:FilePath/Altstadt%20-%20Schmalkalden%20-%2020120408.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Altstadt%20-%20Schmalkalden%20-%2020120408.JPG"}'::text[], 4),
    (v_route, 'Trusetalský vodopád', 'Nejvyšší vodopád Durynska padá u obce Trusetal ve třech kaskádách z 58 metrů — byl sice v 19. století vytvořen uměle přivedením horské vody, ale scenérie s vyhlídkou Teufelskanzel je dokonalá. Podél vodopádu vede schodiště s můstky, dole je parkoviště přímo u silnice. Poslední zastávka před návratem do Eisenachu přes hřebenovou silnici.', 50.79083, 10.41472, 'https://commons.wikimedia.org/wiki/Special:FilePath/Auf%20der%20Teufelskanzel%20am%20Trusetaler%20Wasserfall%202H1A8928WI.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Auf%20der%20Teufelskanzel%20am%20Trusetaler%20Wasserfall%202H1A8928WI.jpg"}'::text[], 5);
