  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Fulda – barokní dóm', 'Biskupské město s velkolepým barokním dómem, kde je pohřben svatý Bonifác, apoštol Němců, a s barokní čtvrtí kolem městského zámku a zahrad. Kompaktní centrum se projde za hodinku a nabízí desítky kaváren. Odtud se vyráží na východ do kopců Rhönu.', 50.55417, 9.67139, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fulda%20-%20Dom%20-%20Panorama.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fulda%20-%20Dom%20-%20Panorama.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dom%20zu%20Fulda.JPG"}'::text[], 0),
    (v_route, 'Point Alpha (Geisa)', 'Bývalé americké pozorovací stanoviště přímo na železné oponě, kde stály tanky NATO a Varšavské smlouvy čtyřicet let proti sobě — dnes autentický památník studené války s věžemi, zátarasy a zachovaným pásem hranice. Z vyhlídky je vidět údolí Ulsteru, kudy vedla smrtící hranice. Silné místo, které vezme za srdce i otrlé.', 50.68528, 9.93167, 'https://commons.wikimedia.org/wiki/Special:FilePath/Geisa%20point%20alpha%20blick%20ulstertal%20ds%20wv%2030%2009%202011.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Geisa%20point%20alpha%20blick%20ulstertal%20ds%20wv%2030%2009%202011.jpg"}'::text[], 1),
    (v_route, 'Schwarzes Moor', 'Jedno z nejvýznamnějších vrchovištních rašelinišť střední Evropy na trojmezí Bavorska, Hesenska a Durynska. Naučná stezka po dřevěných chodnících vede kolem temných rašelinných ok s pokroucenými břízami — krajina spíš skandinávská než německá. Hned vedle parkoviště začíná panoramatická Hochrhönstraße.', 50.52167, 10.07417, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rh%C3%B6n%20schwarzes%20Moor.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rh%C3%B6n%20schwarzes%20Moor.JPG"}'::text[], 2),
    (v_route, 'Klášter Kreuzberg – klášterní pivovar', 'Svatá hora Franků (928 m) s františkánským klášterem, jehož mniši vaří od roku 1731 proslulé tmavé pivo — klášterní šenk s kaštanovou zahradou je vyhlášeným cílem motorkářů z celého Německa. Ke klášteru vede pěkné stoupání z Bischofsheimu a od Golgoty nad klášterem je daleký rozhled. Jezdci sáhnou po nealko variantě nebo si pivo odvezou v lahvi; k jídlu nechybí pořádné klášterní svačiny.', 50.37028, 9.97611, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rhoen%20Kloster%20Kreuzberg.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rhoen%20Kloster%20Kreuzberg.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kloster%20Kreuzberg%2019.jpg"}'::text[], 3),
    (v_route, 'Wasserkuppe', 'Nejvyšší hora Rhönu (950 m) a světová kolébka bezmotorového létání — už od roku 1911 tu piloti využívají stoupavé proudy nad holými svahy a provoz větroňů, rogal a padáků nad hlavou je tu nepřetržitý. Vrcholu dominuje bílá radarová kopule z dob studené války, dnes vyhlídka. Nahoru vede silnice až k letišti s muzeem plachtění a několika restauracemi.', 50.49806, 9.9375, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wasserkuppe%20Radom.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wasserkuppe%20Radom.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Fliegerdenkmal,%20Wasserkuppe.jpg"}'::text[], 4),
    (v_route, 'Milseburg', 'Čedičový suk s dramatickou siluetou, keltským hradištěm na vrcholu a kaplí svatého Gangolfa — perla hesenského Rhönu. Od parkoviště pod horou vede na vrchol půlhodinová stezka mezi skalami, odměnou je jeden z nejhezčích výhledů v pohoří. Poslední zastávka před sjezdem zpátky do Fuldy.', 50.545, 9.89833, 'https://commons.wikimedia.org/wiki/Special:FilePath/Milseburg-Auersberg.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Milseburg-Auersberg.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Milseburg,%20Kreuzigungsgruppe%20am%20Berggipfel.jpg"}'::text[], 5);
