  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Hohenzollern', 'Rodové sídlo pruských králů a německých císařů trůní na osamělém kuželu 855 metrů nad mořem — když se ráno válí mlha v údolích, vypadá hrad jako zámek plující na oblacích. Novogotická přestavba z 19. století ukrývá korunovační klenoty pruských králů. Nahoru vede serpentinová silnička k parkovišti, dál kyvadlový bus nebo pěšky lesem.', 48.32333, 8.9675, 'https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Hohenzollern%20-%206620-2.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Hohenzollern%20-%206620-2.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Burg%20Hohenzollern%2010-2016.jpg"}'::text[], 0),
    (v_route, 'Zámek Lichtenstein', 'Miniaturní romantický zámeček přilepený na hraně 250metrové vápencové stěny nad údolím Echaz — inspirací byl rytířský román Lichtenstein a přezdívá se mu pohádkový zámek Württemberska. Z nádvoří a mostku přes propast jsou závratné výhledy do údolí. Stoupání od Honau serpentinami je jedno z nejoblíbenějších v Albě.', 48.40639, 9.25778, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Lichtenstein%2004-2010.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Lichtenstein%2004-2010.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Lichtenstein%20(W%C3%BCrttemberg).jpg"}'::text[], 1),
    (v_route, 'Uracher Wasserfall (Bad Urach)', 'Vodopád padající 37 metrů přes mechem obrostlý travertinový práh do bukového údolí patří k nejnavštěvovanějším přírodním divům Švábské Alby. Od parkoviště v údolí vede k vodopádu rovinatá procházka podél potoka, kdo chce, vystoupá až na horní hranu. Lázeňské městečko Bad Urach s hrázděným náměstím stojí za krátkou objížďku.', 48.48694, 9.37806, 'https://commons.wikimedia.org/wiki/Special:FilePath/Uracher%20Wasserfall.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Uracher%20Wasserfall.jpg"}'::text[], 2),
    (v_route, 'Zámek Sigmaringen', 'Mohutná rezidence švábské větve Hohenzollernů se zvedá přímo ze skály nad Dunajem uprostřed města — druhý největší městský zámek Německa s jednou z největších soukromých zbrojnic Evropy (přes 3000 kusů). Interiéry jsou přístupné s průvodcem. Od zámku začíná nejkrásnější úsek kaňonu horního Dunaje směrem na Beuron.', 48.08778, 9.21639, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Sigmaringen%202022.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Sigmaringen%202022.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sigmaringen%20schloss.jpg"}'::text[], 3),
    (v_route, 'Knopfmacherfelsen', 'Vyhlídková skála 120 metrů nad meandrem mladého Dunaje s výhledem na kaňon, klášter Beuron i hrad Wildenstein na protější stěně — nejslavnější pohled celého Horního Podunají. Parkoviště je u silnice mezi Fridingenem a Beuronem, k vyhlídce pár minut chůze. Za ranního protisvětla nezapomenutelné.', 48.03667, 8.97139, 'https://commons.wikimedia.org/wiki/Special:FilePath/Knopfmacherfelsen%20im%20Donautal.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Knopfmacherfelsen%20im%20Donautal.jpg"}'::text[], 4),
    (v_route, 'Klášter Beuron', 'Benediktinské arciopatství v nejkrásnější zákrutě dunajského kaňonu, obklopené vápencovými věžemi a lesy — centrum vlastního uměleckého stylu beuronské školy a gregoriánského chorálu. Barokní klášterní kostel je volně přístupný, v klášterním obchodě prodávají mnišské likéry a med. Odtud zpět přes plošinu Velkého Heubergu do Hechingenu.', 48.05, 8.96722, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kloster%20Beuron%202009%20Blick%20von%20Nordwesten.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kloster%20Beuron%202009%20Blick%20von%20Nordwesten.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Donautal-beuron.jpg"}'::text[], 5);
